def is_balanced(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def match_parens(lst):
    if len(lst) != 2:
        return 'No'

    for i in range(2):
        if any(char not in ['(', ')'] for char in lst[i]):
            return 'No'

    for i in range(2):
        for j in range(2):
            if is_balanced(lst[i] + lst[j]):
                return 'Yes'

    return 'No'

